using Intropy.Topology;
using OtlpProtocol = Intropy.Topology.Model.OtlpProtocol;

/// <summary>The students system: what exists, and what connects it.</summary>
public sealed class StudentsSystem : ISystemDefinition
{
    public string SystemName => "students";

    public void Define(SystemBuilder builder)
    {
        builder.Otlp("http://localhost:4318")
            .WithProtocol(OtlpProtocol.HttpProtobuf)
            .WithHeader("Authorization", "Bearer REDACTED");
        // The only reader of Ladok's Atom feed: every entry becomes a tier 1 CloudEvent on
        // ladok-events. Its scaffold record carries one message (records hold a single
        // publishes value); the other six are declared here by hand.
        builder.AddExtractor("ladok-extractor")
            .From(Ports.LadokExtractorSource)
            .Publishes(Messages.KurstillfalleKlarmarkerat)
            .Publishes(Messages.AntagningCreated)
            .Publishes(Messages.RegistreringCreated)
            .Publishes(Messages.OmregistreringCreated)
            .Publishes(Messages.AntagningDeleted)
            .Publishes(Messages.RegistreringDeleted)
            .Publishes(Messages.OmregistreringDeleted)
            // No idempotency service: the extractor publishes at least once and consumers
            // deduplicate on the CloudEvent id (the HandelseUID).
            .Calls(Services.BusinessIncidents);

        // All three consumers enrich through Ladok's REST API (ladok-api): the kurstillfälle and its
        // utbildningstyp decide relevance, each consumer by its own rule, within its own rate budget.

        // Kurstillfällen to AD: a kurstillfälle of kategori KURS that is klarmarkerat gets its three
        // groups (antagna, registrerade, omregistrerade); groups that exist are left alone.
        builder.AddLoader("ad-group-loader")
            .Subscribes(Messages.KurstillfalleKlarmarkerat, configure: subscription => subscription.IgnoreOthers())
            .LooksUp(Ports.LadokApi)
            .To(Ports.Ad)
            .Calls(Services.BusinessIncidents);

        // Ladok's six participation events, read straight from ladok-events by two independent
        // consumers. The other Ladok events on the topic are acknowledged unread.

        // Participations to IAM: a participation created on a kurstillfälle that entitles a
        // student account creates the account or extends its validity. IAM propagates it to AD,
        // which is what ad-membership's workflows wait for.
        builder.AddLoader("student-account-loader")
            .Subscribes(Messages.AntagningCreated, configure: subscription => subscription
                .AlsoHandles(Messages.RegistreringCreated)
                .AlsoHandles(Messages.OmregistreringCreated)
                .IgnoreOthers())
            .LooksUp(Ports.LadokApi)
            .To(Ports.Iam)
            .Calls(Services.BusinessIncidents);

        // Participations to AD: a long-running process per student. Its book orders the student's
        // events by Ladok's sequence (deleted before created, duplicates, out of order), works out
        // the memberships, and applies them once IAM has established the student in AD, checking
        // AD on a timer while it waits. A loader from the outside; its workflows keep their
        // instances in the minted state.
        builder.AddLoader("ad-membership")
            .Subscribes(Messages.AntagningCreated, configure: subscription => subscription
                .AlsoHandles(Messages.RegistreringCreated)
                .AlsoHandles(Messages.OmregistreringCreated)
                .AlsoHandles(Messages.AntagningDeleted)
                .AlsoHandles(Messages.RegistreringDeleted)
                .AlsoHandles(Messages.OmregistreringDeleted)
                .IgnoreOthers())
            .LooksUp(Ports.LadokApi)
            .To(Ports.Ad)
            .Calls(Services.BusinessIncidents)
            .WithWorkflowState();
    }
}
using Intropy.Topology;

/// <summary>The system's ports: the named interfaces its edge blocks reach the outside world through. The name is each port's whole identity — the Dapr binding component uses the same name, while its deployed type, address, and credentials are environment-owned deployment configuration.</summary>
public static class Ports
{
    /// <summary>Ladok's Atom feed: deployed as a Dapr HTTP output binding (<c>bindings.http</c>) to Ladok, with the client certificate (mTLS) in the binding's metadata. Locally mocked from <c>mocks/ladok-feed.openapi.yaml</c>: the development definition resolves it to a <c>bindings.http</c> binding of the same name on the Microcks mock.</summary>
    public static readonly PortRef LadokExtractorSource = PortRef.Define("ladok-extractor-source");

    /// <summary>AD's API, where ad-group-loader creates groups and ad-membership writes group memberships and checks for accounts: deployed as a Dapr HTTP output binding (<c>bindings.http</c>). Locally mocked from <c>mocks/ad-api.openapi.yaml</c> (<c>mocks/ad-api/generate.py</c>): every student is established in AD 10 s after the first ask, except Bo.</summary>
    public static readonly PortRef Ad = PortRef.Define("ad");

    /// <summary>IAM's API, where student-account-loader creates accounts and extends their validity; IAM establishes them in AD: deployed as a Dapr HTTP output binding (<c>bindings.http</c>). Locally mocked from <c>mocks/iam-api.openapi.yaml</c> (<c>mocks/iam-api/generate.py</c>).</summary>
    public static readonly PortRef Iam = PortRef.Define("iam");

    /// <summary>Ladok's REST API, read for enrichment (a kurstillfälle, its utbildningstyp): deployed as a Dapr HTTP output binding (<c>bindings.http</c>) with the client certificate (mTLS) in its metadata, like the feed. Rate limited per client certificate. Locally mocked from <c>mocks/ladok-api.openapi.yaml</c> (<c>mocks/ladok-api/generate.py</c>).</summary>
    public static readonly PortRef LadokApi = PortRef.Define("ladok-api");
}
using Intropy.Topology;

// The platform services the system's blocks call through Dapr service invocation.
// Every extractor and loader calls both (the framework's block builders require
// idempotency and business-incident routing), wired in the system definition via
// `.Calls(...)`. A ref that no component calls never enters the topology. The
// development definition substitutes OpenAPI-backed mocks for local runs.
public static class Services
{
    /// <summary>The idempotency service (Dapr app id 'idempotency-service').</summary>
    public static readonly ServiceRef Idempotency = ServiceRef.Define("idempotency-service");

    /// <summary>The business-incident service (Dapr app id 'business-incident-service').</summary>
    public static readonly ServiceRef BusinessIncidents = ServiceRef.Define("business-incident-service");
}

