function FlowCanvas({
  nodes,
  edges,
  onNodesChange,
  onSelect,
  onInspect,
  slotMenu,
  onSeed,
  fitSignal,
  theme,
}: {
  nodes: Node[]
  edges: Edge[]
  onNodesChange: Parameters<typeof ReactFlow>[0]['onNodesChange']
  onSelect: (path: string) => void
  onInspect: (selection: FlowSelection | null) => void
  slotMenu: SlotMenu
  onSeed: (component: string) => void
  fitSignal: string
  theme: 'light' | 'dark'
}) {
