import { BaseEdge, type Edge, type EdgeProps } from '@xyflow/react'

export type LookupEdgeType = Edge<Record<string, unknown>, 'lookup'>

// How far the bus runs down from the lookup card before turning, and how far
// right of its components' cards the trunk runs.
const DROP = 20
const GUTTER = 18

// LookupEdge draws a lookup port → component edge as a bus: down from the
// port's card, across to a trunk in the gutter right of the component column,
// down the trunk and into the card's top-right. Components that share a column
// share the trunk, so a port consulted by a stack of cards reads as one line
// branching into each, never as a line threaded through the cards above.
export function LookupEdge({
  id,
  sourceX,
  sourceY,
  targetX,
  targetY,
  markerStart,
  markerEnd,
}: EdgeProps<LookupEdgeType>) {
  const turnY = sourceY + DROP
  const trunkX = targetX + GUTTER
  const path = `M ${sourceX} ${sourceY} V ${turnY} H ${trunkX} V ${targetY} H ${targetX}`
  return <BaseEdge id={id} path={path} markerStart={markerStart} markerEnd={markerEnd} />
}

