package dashboard

import (
	"fmt"
	"net/http"
	"path/filepath"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// Graph status values CatalogEntry.GraphStatus takes.
const (
	graphMatched       = "matched"
	graphNoTopology    = "no-topology"
	graphNotInGraph    = "not-in-graph"
	graphTopologyError = "topology-error"
	graphPending       = "pending"
)

// Check severity values.
const (
	severityWarn = "warn"
	severityInfo = "info"
)

// CatalogEntry is the /api/catalog/{path} payload: the integration's header
// facts and its checks, assembled from the cached topology report and the
// scaffold walk. Deployment state is NOT embedded — it stays on
// /api/deploy/{path}, which costs a GitOps checkout refresh.
type CatalogEntry struct {
	// Component is the header identity: the graph's name for the component
	// when GraphStatus is "matched", the scaffold record's name otherwise.
	Component string `json:"component"`

	// Kind is the topology block kind. Empty in every non-matched state.
	Kind string `json:"kind,omitempty"`

	// System is the declared system name, when the integration has one.
	System string `json:"system,omitempty"`

	// SystemPath is the system directory the topology record joins on. It
	// travels so a consumer fetching the topology (for the contract registry,
	// which this payload does not embed) can match the right system.
	SystemPath string `json:"systemPath,omitempty"`

	// Contracts the component publishes/subscribes on, resolved against the
	// topology's contracts registry. Absent in every non-matched state.
	Publishes  []ContractEdge `json:"publishes,omitempty"`
	Subscribes []ContractEdge `json:"subscribes,omitempty"`

	// Repository is "owner/repo" from the scaffold record — provenance only.
	// The record can go stale, so identity and contracts come from the graph.
	Repository string `json:"repository,omitempty"`

	// GraphStatus: "matched" | "no-topology" | "not-in-graph" |
	// "topology-error" | "pending".
	GraphStatus string `json:"graphStatus"`

	// TopologyPending is true while the first topology computation is in
	// flight. The header renders from scaffold data; contracts are unknown.
	TopologyPending bool `json:"topologyPending,omitempty"`

	// Checks are graph-derived findings, warns before infos.
	Checks []Check `json:"checks,omitempty"`
}

// ContractEdge is one end of a pub/sub wire a component sits on: one message
// it publishes or routes, or — for a record older than message wiring — one
// topic.
type ContractEdge struct {
	Pubsub string `json:"pubsub"`
	Topic  string `json:"topic"`

	// Message is the message the component publishes or routes on the topic.
	// Absent for a record older than message wiring.
	Message string `json:"message,omitempty"`

	// Contract is the message's contract (the topic's, for an older record):
	// its shortName when the registry carries it, its raw name otherwise —
	// the same lookup the flow view's detail panel makes.
	Contract string `json:"contract,omitempty"`

	// When is the content filter the component's route applies to the
	// message's events. Absent on publishes and on unfiltered routes.
	When string `json:"when,omitempty"`

	// Publishers and Subscribers are every component on each end of the wire —
	// the message's when it is known, the topic's otherwise — so a contract can
	// be inspected as the connection between components rather than as a
	// name. Absent when the wire declares neither.
	Publishers  []string `json:"publishers,omitempty"`
	Subscribers []string `json:"subscribers,omitempty"`
}

// Check is one finding about the integration's place in the system graph.
type Check struct {
	// Severity: "warn" | "info".
	Severity string `json:"severity"`
	Message  string `json:"message"`
}

// catalog serves one integration's catalog entry: header identity and
// contracts from the cached topology report when it has the component, from
// the scaffold record otherwise. It never triggers the topology computation —
// the flow view owns that cost — so a request against a cold cache answers
// promptly with the component pending.
func (s *apiServer) catalog(w http.ResponseWriter, r *http.Request) {
	s.byPath(w, r, func(e template.ScaffoldEntry, systems map[string]string) any {
		sum := s.summarize(e, systems)
		loaded, entries, errs := s.topologiesLoaded()
		if !loaded {
			// Answer pending now, compute in the background: the pending answer
			// becomes a matched one on the next fetch, without the request
			// queueing behind a dotnet build per host.
			s.warmTopologies()
		}
		return buildCatalogEntry(sum, systems, loaded, entries, errs)
	})

  if (!topology || !edge.contract) return undefined
  return topology.contracts?.find((c) => c.name === edge.contract || c.shortName === edge.contract)
}

/** Component identity and contracts. In non-matched states the header renders
 *  from the scaffold record — provenance, not fact — and says where contracts
 *  went. */
function CatalogHeader({
  entry,
  onSelectContract,
}: {
  entry: CatalogEntry
  onSelectContract: (edge: ContractEdge) => void
}) {
  const matched = entry.graphStatus === 'matched'

  return (
    <header className="catalog-header">
      <h1 className="detail-title">
        {entry.component}
        {entry.kind && <span className="catalog-kind">{entry.kind}</span>}
        {entry.system && <span className="catalog-system">{entry.system}</span>}
      </h1>
      {!matched && <p className="muted catalog-provenance">identity from scaffold record</p>}

      {matched ? (
        <div className="catalog-contracts">
          <ContractGroup label="Publishes" edges={entry.publishes} onSelect={onSelectContract} />
          <ContractGroup label="Subscribes" edges={entry.subscribes} onSelect={onSelectContract} />
        </div>
      ) : (
        <p className="muted">{contractsUnknown(entry)}</p>
      )}

      {entry.repository && (
        <p className="catalog-repo">
          <a
            href={`https://github.com/${entry.repository}`}
            target="_blank"
            rel="noreferrer"
            title={`Scaffold source repository: ${entry.repository}`}
          >
            <OpenInNewIcon className="icon" aria-hidden />
            {entry.repository}
          </a>
        </p>
      )}
    </header>
  )
}

function ContractGroup({
  label,
  edges,
  onSelect,
}: {
  label: string
