// registryDefinition looks up a workspace message in the registry. No
// registry configured, or a registry that does not declare the message, is
// nothing to show; a registry that cannot be read is a warning, since the
// workspace entry still answers.
func registryDefinition(cmd *cobra.Command, ref string) *MessageEntry {
	url, err := resolveRegistryURL(messageShowOpts.registryURL)
	if err != nil {
		return nil
	}
	client, err := newXRegistryClient(url)
	if err != nil {
		fmt.Fprintln(cmd.ErrOrStderr(), "warning:", err)
		return nil
	}
	e, err := registryMessage(cmd.Context(), client, ref)
	var notFound *xregistry.MessageNotFoundError
	switch {
	case errors.As(err, &notFound):
		return nil
	case err != nil:
		fmt.Fprintf(cmd.ErrOrStderr(), "warning: registry definition not shown: %v\n", err)
		return nil
	}
	return e
}

// printMessage writes one message: human rows to stdout, or the JSON
// document. Diagnostics never share the stdout stream.
func printMessage(cmd *cobra.Command, e *MessageEntry, output string) error {
	if output == "json" {
		enc := json.NewEncoder(cmd.OutOrStdout())
		enc.SetIndent("", "  ")
		return enc.Encode(e)
	}

	fmt.Fprintf(cmd.OutOrStdout(), "message:   %s\n", e.Message)
	fmt.Fprintf(cmd.OutOrStdout(), "source:    %s\n", e.Source)
	if e.Type != "" && e.Type != e.Message {
		fmt.Fprintf(cmd.OutOrStdout(), "type:      %s\n", e.Type)
	}
	if e.Envelope != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "envelope:  %s\n", e.Envelope)
	}
	if e.Group != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "group:     %s\n", e.Group)
	}
	if e.Path != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "path:      %s\n", e.Path)
	}
	if e.Contract != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "contract:  %s\n", e.Contract)
	}
	if e.Topic != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "topic:     %s\n", e.Topic)
	}
	if len(e.Channels) > 0 {
		fmt.Fprintf(cmd.OutOrStdout(), "channels:  %s\n", strings.Join(e.Channels, ", "))
	}
	if e.DataSchema != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "dataschema: %s\n", e.DataSchema)
	}
	if e.DataSchemaURL != "" {
		fmt.Fprintf(cmd.OutOrStdout(), "dataschemaurl: %s\n", e.DataSchemaURL)
	}
	for _, kv := range e.EnvelopeMeta {
		required := ""
		if kv.Required {
			required = " (required)"
		}
		value := "-"
		if kv.Value != "" {
			value = kv.Value
		}
		fmt.Fprintf(cmd.OutOrStdout(), "envelope %s: %s%s\n", kv.Name, value, required)
	}
	if e.Registry != nil {
		fmt.Fprintln(cmd.OutOrStdout())
		return printMessage(cmd, e.Registry, output)
	}
	return nil
}

