/** ContractDetail is the catalog's inspector for one contract: the wire it
 *  travels (which components publish and subscribe), and its field tree. The
 *  schema comes from the topology's contracts registry when the host emits
 *  one; until then a clearly-labelled placeholder shows what the section will
 *  look like. */
export function ContractDetail({ entry, edge, contract, onClose }: Props) {
  const schema = contract?.schema
  const name = edge.contract ?? edge.message ?? edge.topic

  return (
    <aside className="flow-detail contract-detail">
      <div className="flow-detail-head">
        <span className="flow-detail-title">{name}</span>
        <button
          type="button"
          className="flow-detail-close"
          onClick={onClose}
          aria-label="Close details"
        >
          ×
        </button>
      </div>

      <Section title="Wire" icon={CategoryIcon}>
        <div className="meta-grid">
          <Wire label="Topic" value={`${edge.pubsub}/${edge.topic}`} />
          {edge.message && <Wire label="Message" value={edge.message} />}
          {edge.when && <Wire label="Route filter" value={edge.when} />}
          <Wire label="Published by" value={list(edge.publishers, entry.component)} />
          <Wire label="Subscribed by" value={list(edge.subscribers, entry.component)} />
        </div>
      </Section>

      <Section title="Schema" icon={CategoryIcon}>
        {schema ? (
          <SchemaTree schema={schema} />
        ) : (
          <>
            <p className="contract-placeholder-note">
              The system host does not publish a schema yet — this is placeholder
              data to show what the section will render once it does.
            </p>
            <SchemaTree schema={PLACEHOLDER_SCHEMA} />
          </>
        )}
      </Section>

      {contract?.fingerprint && (
        <p className="muted contract-fingerprint">fingerprint {contract.fingerprint}</p>
      )}
    </aside>
  )
}

function Wire({ label, value }: { label: string; value: string }) {
  return (
    <div className="meta">
      <span className="meta-label">{label}</span>
      <span className="meta-value">{value}</span>
    </div>
  )
}

/** list renders the components on one end of the wire, marking this one. The
 *  topology's publisher/subscriber lists are the source; the component the
 *  contract was clicked from is annotated rather than repeated blindly. */
function list(names: string[] | undefined, self: string): string {
  if (!names || names.length === 0) return '—'
  return names.map((n) => (n === self ? `${n} (this)` : n)).join(', ')
}
import { useEffect, useState } from 'react'
import {
  api,
  type CatalogCheck,
  type CatalogEntry,
  type Contract,
  type ContractEdge,
  type DeployState,
  type Topology,
} from '../api'
import { Section } from './chrome'
import { CatalogEnvironments } from './CatalogEnvironments'
import { ContractDetail } from './ContractDetail'
import { CategoryIcon, FilterIcon, OpenInNewIcon } from '../icons'

export interface DeployProps {
  state: DeployState | null
  loading: boolean
  refreshing: boolean
  onRefresh: () => void
}

interface Props {
  path: string | null
  deploy: DeployProps
}

// How often to re-fetch a pending catalog entry, and for how long. The first
// topology computation runs a dotnet build per system host, so a single retry
// would routinely lose the race; polling every few seconds for up to three
// minutes covers a cold build without polling forever. After the cap the
// refresh is left to the user.
const PENDING_RETRY_MS = 5_000
const PENDING_RETRY_CAP = 36

/** The catalog view: what a component is (header), what needs attention
 *  (checks), and what every environment runs. Identity and contracts come from
 *  the system topology graph — the scaffold record is provenance only, because
 *  it can go stale. */
export function Catalog({ path, deploy }: Props) {
  const [entry, setEntry] = useState<CatalogEntry | null>(null)
  const [selectedContract, setSelectedContract] = useState<ContractEdge | null>(null)
  const [topology, setTopology] = useState<Topology | null>(null)

  useEffect(() => {
    if (!path) {
      setEntry(null)
      setSelectedContract(null)
      setTopology(null)
      return
    }
    setEntry(null)
    setSelectedContract(null)
    setTopology(null)
    let current = true
    let timer: ReturnType<typeof setTimeout> | undefined
    let attempts = 0

    const load = () => {
      api
        .catalog(path)
        .then((e) => {
          if (!current) return
          setEntry(e)
          // A cold topology cache answers pending while the server computes
          // the graph in the background; keep re-fetching until it resolves
          // or the cap leaves the refresh to the user.
          if (e.topologyPending && attempts < PENDING_RETRY_CAP) {
            attempts++
            timer = setTimeout(load, PENDING_RETRY_MS)
          }
        })
        .catch(() => {
          if (current) setEntry(null)
        })
    }
    load()
    return () => {
      current = false
      if (timer) clearTimeout(timer)
    }
  }, [path])

  // The contract registry (schemas) rides on the topology payload, which the
  // catalog endpoint does not embed. Fetch it once the entry names a system,
  // matched by systemPath so the right system's registry is used.
  useEffect(() => {
    if (!entry?.systemPath) {
      setTopology(null)
      return
    }
    let current = true
    api
      .topologies()
      .then((report) => {
        if (!current) return
        setTopology(report.topologies.find((t) => t.path === entry.systemPath) ?? null)
      })
      .catch(() => {})
    return () => {
      current = false
    }
  }, [entry?.systemPath])

  if (!path) {
    return <p className="empty">Select an integration to see its catalog entry.</p>
  }
  if (!entry) {
    return <p className="empty">Loading…</p>
  }

  const checks = collectChecks(entry, deploy.state)

  return (
    <article className="detail">
      <CatalogHeader entry={entry} onSelectContract={setSelectedContract} />
      <CatalogChecks checks={checks} />
      <CatalogEnvironments
        state={deploy.state}
        loading={deploy.loading}
        refreshing={deploy.refreshing}
        onRefresh={deploy.onRefresh}
      />
      {selectedContract && (
        <ContractDetail
          entry={entry}
          edge={selectedContract}
          contract={contractFor(selectedContract, topology)}
          onClose={() => setSelectedContract(null)}
        />
      )}
    </article>
  )
}

