// Package message implements the message commands: `message list`,
// `message show` and `message schema`. Each command is one function taking
// its options and the streams it writes to, so the command line and the
// dashboard run the same code and cannot disagree about a message — the
// cobra commands in cmd/intropy only parse flags and call in, the way the
// deploy commands call internal/deploy.
//
// Everything here is read-only: the read-only xRegistry, plus what the
// workspace's scaffold records declare through scalar publishes values.
package message

import (
	"cmp"
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// Where an Entry came from.
const (
	SourceRegistry  = "registry"
	SourceWorkspace = "workspace"
)

// Output formats the commands accept.
const (
	OutputPlain = "plain"
	OutputJSON  = "json"
)

// Entry is one message as the message commands emit it, in JSON output.
// Source marks where the entry came from: "registry" (external, with its
// producing channels and schema pin) or "workspace" (internal, a publishes
// declaration in a scaffold record). One shape for both, so the human table,
// the JSON document, and the show detail cannot drift apart.
type Entry struct {
	Message string `json:"message"`
	Source  string `json:"source"`

	Group          string   `json:"group,omitempty"`
	Type           string   `json:"type,omitempty"`
	Envelope       string   `json:"envelope,omitempty"`
	Channels       []string `json:"channels,omitempty"` // <pubsub>/<topic>
	DataSchema     string   `json:"dataschema,omitempty"`
	DataSchemaURL  string   `json:"dataschemaurl,omitempty"`
	DataSchemaName string   `json:"dataschemaname,omitempty"`
	Contract       string   `json:"contract,omitempty"`
	Topic          string   `json:"topic,omitempty"` // workspace: the topic the record publishes on
	Path           string   `json:"path,omitempty"`  // workspace: the record's project directory
	EnvelopeMeta   []KV     `json:"envelopeMetadata,omitempty"`

	// Registry is the registry's definition of a workspace message the
	// registry also declares: show prints both, never one hiding the other.
	Registry *Entry `json:"registry,omitempty"`
}

// KV is one envelope metadata attribute as JSON output: attribute name,
// value, and whether the envelope requires it.
type KV struct {
	Name     string `json:"name"`
	Value    string `json:"value,omitempty"`
	Required bool   `json:"required,omitempty"`
}

// NoRegistryError reports that no xRegistry is configured. It is the user's
// to fix — the message names every way to set one — so the command layer
// maps it to a usage error.
type NoRegistryError struct{ err error }

func (e *NoRegistryError) Error() string { return e.err.Error() }
func (e *NoRegistryError) Unwrap() error { return e.err }

// RegistryURL layers the --registry-url flag over the config, the same
// precedence every other setting uses. An unconfigured registry is a
// *NoRegistryError; there is no guessed default.
func RegistryURL(flagURL string) (string, error) {
	cfg, err := config.Load()
	if err != nil {
		return "", err
	}
	url, err := cfg.Resolve(config.Flags{RegistryURL: flagURL}).RequireRegistryURL()
	if err != nil {
		return "", &NoRegistryError{err: err}
	}
	return url, nil
}

// NewClient builds the xRegistry client for url.
func NewClient(url, userAgent string) (*xregistry.Client, error) {
	return xregistry.New(url, xregistry.WithUserAgent(userAgent))
}

// registryClient resolves the registry URL and builds its client.
func registryClient(flagURL, userAgent string) (*xregistry.Client, error) {
	url, err := RegistryURL(flagURL)
	if err != nil {
		return nil, err
	}
	return NewClient(url, userAgent)
}

// Workspace indexes the publishes declarations under dir. Scan and parse
// warnings are non-fatal: a malformed sibling record must not hide the
// messages the rest of the workspace declares.
func Workspace(dir string, warnf func(error)) []Entry {
	entries, warnings := template.ListScaffolds(dir)
	for _, w := range warnings {
		warnf(w)
	}
	seen := map[string]bool{}
	var out []Entry
	for _, e := range entries {
		// Malformed records yield nothing here — listing must show what is
		// resolvable; assembly is the surface that reports the record.
		publications := template.SoftPublications(e)
		topic, _ := template.SoftValue(e.Values, template.KeyChannel)
		for _, p := range publications {
			if seen[p.Message] {
				continue
			}
			seen[p.Message] = true
			out = append(out, Entry{
				Message:  p.Message,
				Source:   SourceWorkspace,
				Type:     p.Message,
				Contract: p.PayloadType,
				Topic:    cmp.Or(topic, p.Message),
				Path:     e.Path,
			})
		}
	}
	sortEntries(out)
	return out
}

// sortEntries orders a merged list: registry messages by ref, then workspace
// messages by name — the stable order both table and JSON echo.
func sortEntries(entries []Entry) {
	sort.SliceStable(entries, func(i, j int) bool {
		if entries[i].Source != entries[j].Source {
			return entries[i].Source == SourceRegistry
		}
		return entries[i].Message < entries[j].Message
	})
}

// Registry reads the export into entries, optionally narrowed to one group.
// Resolution failures that block wiring (an ambiguous or unreachable
// subscription channel) do not block listing: the table shows the channels it
// can see. All joins happen in memory against one GET /export — the registry
// declares filtering and per-entity reverse lookups out of scope, so there is
// nothing smaller to fetch.
func Registry(ctx context.Context, client *xregistry.Client, group string) ([]Entry, error) {
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, err
	}

	ids := make([]string, 0, len(doc.MessageGroups))
	for id := range doc.MessageGroups {
		ids = append(ids, id)
	}
	sort.Strings(ids)

	var out []Entry
	for _, gid := range ids {
		g := doc.MessageGroups[gid]
		if group != "" && gid != group {
			continue
		}
		for _, mid := range sortedMessageIDs(g) {
			m := g.Messages[mid]
			def := m.DefaultMessage()
			if def == nil {
				continue
			}
			out = append(out, registryEntry(doc, client, &m, gid, def))
		}
	}
	return out, nil
}

// Find finds exactly one registry message by reference — bare message id or
// /messagegroups/<gid>/messages/<mid> xid.
func Find(ctx context.Context, client *xregistry.Client, ref string) (*Entry, error) {
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, err
	}
	msg, group, err := xregistry.FindMessage(doc, ref)
	if err != nil {
		return nil, err
	}
	def := msg.DefaultMessage()
	if def == nil {
		return nil, fmt.Errorf("message %q in group %s carries no definition attributes", ref, group.ID)
	}
	e := registryEntry(doc, client, msg, group.ID, def)
	return &e, nil
}

func registryEntry(doc *xregistry.Export, client *xregistry.Client, m *xregistry.Message, gid string, def *xregistry.MessageVersion) Entry {
	e := Entry{
		Message:  m.ID,
		Source:   SourceRegistry,
		Group:    gid,
		Type:     envelopeType(def),
		Envelope: def.Envelope,
		Channels: xregistry.ProducerChannels(doc, gid),
	}
	if def.DataSchemaXID != "" {
		e.DataSchema = def.DataSchemaXID
		e.DataSchemaName = schemaName(def.DataSchemaXID)
		if xid, err := xregistry.DefaultSchemaVersionXID(doc, def.DataSchemaXID); err == nil {
			e.DataSchemaURL = joinURL(client.BaseURL(), xid)
		}
	}
	e.EnvelopeMeta = envelopeMetadata(def)
	return e
}

// registryDefinition looks up a workspace message in the registry. No
// registry configured, or a registry that does not declare the message, is
// nothing to show; a registry that cannot be read is a warning, since the
// workspace entry still answers.
func registryDefinition(ctx context.Context, flagURL, userAgent, ref string, warnf func(string)) *Entry {
	url, err := RegistryURL(flagURL)
	if err != nil {
		return nil
	}
	client, err := NewClient(url, userAgent)
	if err != nil {
		warnf(err.Error())
		return nil
	}
	e, err := Find(ctx, client, ref)
	var notFound *xregistry.MessageNotFoundError
	switch {
	case errors.As(err, &notFound):
		return nil
	case err != nil:
		warnf(fmt.Sprintf("registry definition not shown: %v", err))
		return nil
	}
	return e
}

func sortedMessageIDs(g xregistry.MessageGroup) []string {
	ids := make([]string, 0, len(g.Messages))
	for id := range g.Messages {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

// envelopeType extracts the CloudEvents type from the envelope metadata.
func envelopeType(def *xregistry.MessageVersion) string {
	if attr, ok := def.EnvelopeMetadata["type"]; ok {
		if s, ok := attr.Value.(string); ok {
			return s
		}
	}
	return ""
}

// envelopeMetadata renders the envelope attributes sorted by name so the
// JSON document is stable across exports.
func envelopeMetadata(def *xregistry.MessageVersion) []KV {
	names := make([]string, 0, len(def.EnvelopeMetadata))
	for n := range def.EnvelopeMetadata {
		names = append(names, n)
	}
	sort.Strings(names)
	out := make([]KV, 0, len(names))
	for _, n := range names {
		a := def.EnvelopeMetadata[n]
		kv := KV{Name: n, Required: a.Required}
		if s, ok := a.Value.(string); ok {
			kv.Value = s
		} else if a.Value != nil {
			kv.Value = fmt.Sprint(a.Value)
		}
		out = append(out, kv)
	}
	return out
}

// schemaName renders the schema xid's resource tail for the table column.
func schemaName(xid string) string {
	if i := strings.LastIndex(xid, "/schemas/"); i >= 0 {
		rest := xid[i+len("/schemas/"):]
		if j := strings.Index(rest, "/"); j >= 0 {
			return rest[:j]
		}
		return rest
	}
	return xid
}

// joinURL joins the registry base URL with a root-relative xid.
func joinURL(base, xid string) string {
	return strings.TrimSuffix(base, "/") + xid
}

package message

import (
	"cmp"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strings"
	"text/tabwriter"

	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// ListOptions configures List.
type ListOptions struct {
	// Dir is the workspace directory whose scaffold records are indexed.
	Dir string
	// Group narrows to one registry message group; workspace messages carry
	// no group and are hidden by it.
	Group        string
	RegistryURL  string
	OutputFormat string
	UserAgent    string
	Stdout       io.Writer
	Stderr       io.Writer
}

// List is `message list`: every message the registry serves, merged with the
// messages the workspace declares.
func List(ctx context.Context, opts ListOptions) error {
	var entries []Entry
	if opts.Group == "" {
		entries = append(entries, Workspace(opts.Dir, func(w error) {
			fmt.Fprintln(opts.Stderr, "warning:", w)
		})...)
	}
	client, err := registryClient(opts.RegistryURL, opts.UserAgent)
	if err != nil {
		return err
	}
	registryEntries, err := Registry(ctx, client, opts.Group)
	if err != nil {
		return err
	}
	entries = append(entries, registryEntries...)

	if opts.OutputFormat == OutputJSON {
		if entries == nil {
			entries = []Entry{}
		}
		return encodeJSON(opts.Stdout, entries)
	}

	if len(entries) == 0 {
		fmt.Fprintln(opts.Stderr, "no messages found")
		return nil
	}

	tw := tabwriter.NewWriter(opts.Stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "MESSAGE\tSOURCE\tGROUP\tCHANNEL\tSCHEMA")
	for _, e := range entries {
		channel := cmp.Or(strings.Join(e.Channels, ", "), e.Topic, "-")
		schema := cmp.Or(e.DataSchemaName, "-")
		fmt.Fprintf(tw, "%s\t%s\t%s\t%s\t%s\n", e.Message, e.Source, e.Group, channel, schema)
	}
	return tw.Flush()
}

// ShowOptions configures Show.
type ShowOptions struct {
	// Ref is the bare message id or a /messagegroups/<gid>/messages/<mid> xid.
	Ref          string
	Dir          string
	RegistryURL  string
	OutputFormat string
	UserAgent    string
	Stdout       io.Writer
	Stderr       io.Writer
}

// Show is `message show`: one message's definition. A workspace publish
// resolves locally, followed by the registry's definition when the configured
// registry declares the message too; everything else reads the registry.
func Show(ctx context.Context, opts ShowOptions) error {
	// Workspace first: a local publish answers without the network.
	for _, e := range Workspace(opts.Dir, func(w error) { fmt.Fprintln(opts.Stderr, "warning:", w) }) {
		if e.Message == opts.Ref {
			e.Registry = registryDefinition(ctx, opts.RegistryURL, opts.UserAgent, opts.Ref, func(msg string) {
				fmt.Fprintln(opts.Stderr, "warning:", msg)
			})
			return printEntry(opts.Stdout, &e, opts.OutputFormat)
		}
	}

	client, err := registryClient(opts.RegistryURL, opts.UserAgent)
	if err != nil {
		return err
	}
	e, err := Find(ctx, client, opts.Ref)
	if err != nil {
		return err
	}
	return printEntry(opts.Stdout, e, opts.OutputFormat)
}

// SchemaOptions configures Schema.
type SchemaOptions struct {
	// Ref is the bare message id or a /messagegroups/<gid>/messages/<mid> xid.
	Ref         string
	Dir         string
	RegistryURL string
	UserAgent   string
	Stdout      io.Writer
	Stderr      io.Writer
}

// NoSchemaError reports a message that resolves but has no registry schema to
// print: the registry declares it without a dataschema, or only the workspace
// declares it. Reason says which, in the CLI's voice.
type NoSchemaError struct {
	Ref    string
	Reason string
}

func (e *NoSchemaError) Error() string {
	return fmt.Sprintf("message %q has no schema: %s", e.Ref, e.Reason)
}

// Schema is `message schema`: the JSON Schema document the message's
// dataschema pins — its default version, the same immutable URL a CloudEvent
// dataschema references — written to Stdout as the registry serves it.
//
// Only the registry carries schemas. A message only the workspace declares is
// a *NoSchemaError naming the record that declares it, rather than a bare
// not-found: the message exists, it just has nothing to print.
func Schema(ctx context.Context, opts SchemaOptions) error {
	client, err := registryClient(opts.RegistryURL, opts.UserAgent)
	if err != nil {
		return err
	}
	doc, err := client.Export(ctx)
	if err != nil {
		return err
	}
	msg, group, err := xregistry.FindMessage(doc, opts.Ref)
	var notFound *xregistry.MessageNotFoundError
	if errors.As(err, &notFound) {
		for _, e := range Workspace(opts.Dir, func(w error) { fmt.Fprintln(opts.Stderr, "warning:", w) }) {
			if e.Message == opts.Ref {
				return &NoSchemaError{
					Ref:    opts.Ref,
					Reason: fmt.Sprintf("only the workspace declares it (%s), and the registry does not", e.Path),
				}
			}
		}
	}
	if err != nil {
		return err
	}
	def := msg.DefaultMessage()
	if def == nil || def.DataSchemaXID == "" {
		return &NoSchemaError{Ref: opts.Ref, Reason: fmt.Sprintf("its registry definition in group %s declares no dataschema", group.ID)}
	}
	xid, err := xregistry.DefaultSchemaVersionXID(doc, def.DataSchemaXID)
	if err != nil {
		return err
	}
	body, err := client.SchemaVersion(ctx, xid)
	if err != nil {
		return err
	}
	return encodeJSON(opts.Stdout, body)
}

func encodeJSON(w io.Writer, v any) error {
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	enc.SetEscapeHTML(false)
	return enc.Encode(v)
}

// printEntry writes one message: human rows, or the JSON document.
// Diagnostics never share the stdout stream.
func printEntry(w io.Writer, e *Entry, output string) error {
	if output == OutputJSON {
		return encodeJSON(w, e)
	}

	fmt.Fprintf(w, "message:   %s\n", e.Message)
	fmt.Fprintf(w, "source:    %s\n", e.Source)
	if e.Type != "" && e.Type != e.Message {
		fmt.Fprintf(w, "type:      %s\n", e.Type)
	}
	if e.Envelope != "" {
		fmt.Fprintf(w, "envelope:  %s\n", e.Envelope)
	}
	if e.Group != "" {
		fmt.Fprintf(w, "group:     %s\n", e.Group)
	}
	if e.Path != "" {
		fmt.Fprintf(w, "path:      %s\n", e.Path)
	}
	if e.Contract != "" {
		fmt.Fprintf(w, "contract:  %s\n", e.Contract)
	}
	if e.Topic != "" {
		fmt.Fprintf(w, "topic:     %s\n", e.Topic)
	}
	if len(e.Channels) > 0 {
		fmt.Fprintf(w, "channels:  %s\n", strings.Join(e.Channels, ", "))
	}
	if e.DataSchema != "" {
		fmt.Fprintf(w, "dataschema: %s\n", e.DataSchema)
	}
	if e.DataSchemaURL != "" {
		fmt.Fprintf(w, "dataschemaurl: %s\n", e.DataSchemaURL)
	}
	for _, kv := range e.EnvelopeMeta {
		required := ""
		if kv.Required {
			required = " (required)"
		}
		fmt.Fprintf(w, "envelope %s: %s%s\n", kv.Name, cmp.Or(kv.Value, "-"), required)
	}
	if e.Registry != nil {
		fmt.Fprintln(w)
		return printEntry(w, e.Registry, output)
	}
	return nil
}

