package dashboard

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/message"
)

// messageProvider describes one message the way `intropy message show` does,
// plus the schema `message show --schema` prints.
//
// Like deployProvider it never fails: a message that cannot be described
// comes back with Error set, and a message that has no schema with
// SchemaError set, because "the registry could not be read" and "this
// message has no schema" must not render the same.
type messageProvider func(ctx context.Context, ref string) messageState

// messageState is one message's definition and schema, or why either is
// missing.
type messageState struct {
	// Message is message show's own JSON document, passed through unchanged
	// so the dashboard and the command line cannot describe the same message
	// differently.
	Message *message.Entry `json:"message,omitempty"`

	// Error is message show's own error, verbatim: an unconfigured registry
	// names every way to configure one, and a paraphrase would be a second
	// thing to keep true.
	Error string `json:"error,omitempty"`

	// Schema is the JSON Schema document message show --schema printed.
	Schema json.RawMessage `json:"schema,omitempty"`

	// SchemaError is message show --schema's own error, verbatim — most
	// often that only the workspace declares the message, which names the
	// record that does.
	SchemaError string `json:"schemaError,omitempty"`

	// Diagnostics is what the commands wrote to stderr, one entry per line.
	Diagnostics []string `json:"diagnostics,omitempty"`

	// ReadAt is when the commands ran.
	ReadAt time.Time `json:"readAt"`
}

// messageTimeout bounds one message lookup: two registry exports and a schema
// fetch. The registry is a small read-only service; a lookup that takes
// longer than this is not going to answer.
const messageTimeout = 30 * time.Second

// messageCommandProvider is the default provider: it runs message show, and
// message show --schema, against the workspace root and decodes what they
// print — the same seam statusCommandProvider uses for deploy status.
func messageCommandProvider(root, version string) messageProvider {
	userAgent := "intropy-cli/" + version
	return func(ctx context.Context, ref string) messageState {
		ctx, cancel := context.WithTimeout(ctx, messageTimeout)
		defer cancel()

		var out, logs bytes.Buffer
		state := messageState{ReadAt: time.Now()}
		err := message.Show(ctx, message.ShowOptions{
			Ref:          ref,
			Dir:          root,
			OutputFormat: message.OutputJSON,
			UserAgent:    userAgent,
			Stdout:       &out,
			Stderr:       &logs,
		})
		if err != nil {
			state.Error = err.Error()
			state.Diagnostics = diagnosticLines(logs.String())
			return state
		}
		var e message.Entry
		if err := json.Unmarshal(out.Bytes(), &e); err != nil {
			state.Error = fmt.Sprintf("read message show output: %v", err)
			return state
		}
		state.Message = &e

		out.Reset()
		err = message.Schema(ctx, message.SchemaOptions{
			Ref:       ref,
			Dir:       root,
			UserAgent: userAgent,
			Stdout:    &out,
			Stderr:    &logs,
		})
		if err != nil {
			state.SchemaError = err.Error()
		} else {
			state.Schema = json.RawMessage(bytes.TrimSpace(out.Bytes()))
		}
		state.Diagnostics = diagnosticLines(logs.String())
		return state
	}
}

// getMessage serves /api/messages/{ref}: one message's definition and schema.
// Registry messages are released and versioned, so a successful answer is
// cached for the life of the process; a failed one is not, so a registry that
// comes back is picked up on the next click.
func (s *apiServer) getMessage(w http.ResponseWriter, r *http.Request) {
	ref := r.PathValue("ref")
	if ref == "" {
		writeError(w, http.StatusBadRequest, "message reference required")
		return
	}
	if s.msg == nil {
		writeError(w, http.StatusServiceUnavailable, "message lookup is not available")
		return
	}

	s.msgMu.Lock()
	cached, ok := s.msgStates[ref]
	s.msgMu.Unlock()
	if ok {
		writeJSON(w, http.StatusOK, cached)
		return
	}

	state := s.msg(r.Context(), ref)
	if state.Error == "" {
		s.msgMu.Lock()
		if s.msgStates == nil {
			s.msgStates = map[string]messageState{}
		}
		s.msgStates[ref] = state
		s.msgMu.Unlock()
	}
	writeJSON(w, http.StatusOK, state)
}

