func TestGetMessageServesTheProviderAnswer(t *testing.T) {
	var asked []string
	provider := func(_ context.Context, ref string) messageState {
		asked = append(asked, ref)
		return messageState{
			Message: &message.Entry{Message: ref, Source: message.SourceRegistry},
			Schema:  json.RawMessage(`{"type":"object"}`),
			settled: true,
		}
	}
	h := testHandlerWith(t, t.TempDir(), providers{topology: emptyTopo, deploy: emptyDeploy, message: provider})

	rec := get(t, h, "/api/messages/io.intropy.fluxia.product.export")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d: %s", rec.Code, rec.Body)
	}
	var got messageState
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatal(err)
	}
	if got.Message == nil || got.Message.Message != "io.intropy.fluxia.product.export" || string(got.Schema) != `{"type":"object"}` {
		t.Errorf("served %s", rec.Body)
	}

	// A settled answer is served from cache: released messages do not change.
	get(t, h, "/api/messages/io.intropy.fluxia.product.export")
	if len(asked) != 1 {
		t.Errorf("provider asked %d times, want 1 (cached)", len(asked))
	}
}

func TestGetMessageDoesNotCacheAFailure(t *testing.T) {
	calls := 0
	provider := func(_ context.Context, ref string) messageState {
		calls++
		return messageState{Error: "fetch xRegistry export: GET http://registry/export: connection refused"}
	}
	h := testHandlerWith(t, t.TempDir(), providers{topology: emptyTopo, deploy: emptyDeploy, message: provider})

	for range 2 {
		rec := get(t, h, "/api/messages/some.message")
		if !strings.Contains(rec.Body.String(), "connection refused") {
			t.Errorf("the command's error should be served verbatim, got %s", rec.Body)
		}
	}
	if calls != 2 {
		t.Errorf("provider asked %d times, want 2: a registry that comes back must be picked up", calls)
	}
}

// The default provider runs message show and message show --schema and
// decodes what they print: the registry's definition and its schema, and for
// a message only the workspace declares, the definition with the command's
// own reason there is no schema.
func TestMessageCommandProvider(t *testing.T) {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /export", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, `{
  "messagegroups": {"io.intropy.fluxia.product": {"messagegroupid": "io.intropy.fluxia.product", "messages": {
    "io.intropy.fluxia.product.export": {"messageid": "io.intropy.fluxia.product.export", "versions": {"1": {
      "versionid": "1", "isdefault": true, "envelope": "CloudEvents/1.0",
      "dataschemaxid": "/schemagroups/fluxia/schemas/product-export.v1"}}}}}},
  "endpoints": {"catalog-extractor": {"endpointid": "catalog-extractor", "usage": ["producer"],
    "channel": "product-pubsub/product-events", "messagegroups": ["/messagegroups/io.intropy.fluxia.product"]}},
  "schemagroups": {"fluxia": {"schemagroupid": "fluxia", "schemas": {"product-export.v1": {"schemaid": "product-export.v1",
    "versions": {"1": {"versionid": "1", "isdefault": true, "xid": "/schemagroups/fluxia/schemas/product-export.v1/versions/1"}}}}}}
}`)
	})
	mux.HandleFunc("GET /schemagroups/fluxia/schemas/product-export.v1/versions/1", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, `{"title":"Product export","type":"object"}`)
	})
	registry := httptest.NewServer(mux)
	t.Cleanup(registry.Close)
	t.Setenv("XDG_CONFIG_HOME", t.TempDir())
	t.Setenv("INTROPY_REGISTRY_URL", registry.URL)

	root := t.TempDir()
	if err := os.MkdirAll(filepath.Join(root, "sink", ".intropy"), 0o755); err != nil {
		t.Fatal(err)
	}
	record := `{"schemaVersion":1,"template":"extractor","owner":"o","repo":"r","version":"v1","blockKind":"extractor","values":{"appId":"sink","publishes":"internal-thing"}}` + "\n"
	if err := os.WriteFile(filepath.Join(root, "sink", ".intropy", "scaffold.json"), []byte(record), 0o644); err != nil {
		t.Fatal(err)
	}
	provide := messageCommandProvider(root, "test")

	got := provide(context.Background(), "io.intropy.fluxia.product.export")
	if got.Error != "" || got.Message == nil {
		t.Fatalf("state = %+v", got)
	}
	if len(got.Message.Channels) != 1 || got.Message.Channels[0] != "product-pubsub/product-events" {
		t.Errorf("channels = %v", got.Message.Channels)
	}
	var schema map[string]any
	if err := json.Unmarshal(got.Schema, &schema); err != nil || schema["title"] != "Product export" {
		t.Errorf("schema = %s (%v)", got.Schema, err)
	}
	if !got.settled {
		t.Error("a definition with its schema is settled")
	}

	got = provide(context.Background(), "internal-thing")
	if got.Error != "" || got.Message == nil || got.Message.Source != message.SourceWorkspace {
		t.Fatalf("state = %+v", got)
	}
	if got.Schema != nil || !strings.Contains(got.SchemaError, "has no schema") || !strings.Contains(got.SchemaError, "sink") {
		t.Errorf("schemaError = %q, want the command's reason naming the record", got.SchemaError)
	}
	if !got.settled {
		t.Error("a definite no-schema answer is settled")
	}
}

