import { useEffect, useState } from 'react'
import { api, type CatalogEntry, type Contract, type ContractEdge, type MessageState } from '../api'
import { Section } from './chrome'
import { SchemaTree } from './FlowDetail'
import { CategoryIcon, OpenInNewIcon } from '../icons'

interface Props {
  /** The catalog entry the message was clicked from — names this component. */
  entry: CatalogEntry
  /** The wire (message on a channel) under inspection. */
  edge: ContractEdge
  /** The host's contract registry entry, when the topology emitted one. */
  contract?: Contract
  onClose: () => void
}

/** ContractDetail is the catalog's inspector for one message: the wire it
 *  travels (which components publish and subscribe), its definition as
 *  `intropy message show` prints it, and its payload schema.
 *
 *  The schema is the one the host's topology emits for the contract when it
 *  does, else the registry's, as `intropy message show --schema` prints it.
 *  When neither has one the panel says why, in the command's own words —
 *  never placeholder data. */
export function ContractDetail({ entry, edge, contract, onClose }: Props) {
  const [state, setState] = useState<MessageState | null>(null)
  const [loading, setLoading] = useState(false)
  const [fetchError, setFetchError] = useState<string | null>(null)

  useEffect(() => {
    setState(null)
    setFetchError(null)
    if (!edge.message) return
    let current = true
    setLoading(true)
    api
      .message(edge.message)
      .then((s) => {
        if (current) setState(s)
      })
      .catch((err: unknown) => {
        if (current) setFetchError(err instanceof Error ? err.message : String(err))
      })
      .finally(() => {
        if (current) setLoading(false)
      })
    return () => {
      current = false
    }
  }, [edge.message])

  const definition = state?.message
  // A workspace message the registry also declares carries the registry's
  // definition beside it: that is where the envelope and schema pin live.
  const registry = definition?.source === 'registry' ? definition : definition?.registry
  const title = edge.message ?? edge.contract ?? edge.topic

  return (
    <aside className="flow-detail contract-detail">
      <div className="flow-detail-head">
        <span className="flow-detail-title">{title}</span>
        <button
          type="button"
          className="flow-detail-close"
          onClick={onClose}
          aria-label="Close details"
        >
          ×
        </button>
      </div>

      <Section title="Wire" icon={CategoryIcon}>
        <div className="meta-grid">
          <Wire label="Channel" value={`${edge.pubsub}/${edge.topic}`} />
          {edge.contract && <Wire label="Contract" value={edge.contract} />}
          {edge.when && <Wire label="Route filter" value={edge.when} />}
          <Wire label="Published by" value={list(edge.publishers, entry.component)} />
          <Wire label="Subscribed by" value={list(edge.subscribers, entry.component)} />
        </div>
      </Section>

      {edge.message && (
        <Section title="Definition" icon={CategoryIcon}>
          {loading && <p className="muted">Reading the message definition…</p>}
          {fetchError && <p className="contract-error">{fetchError}</p>}
          {state?.error && <p className="contract-error">{state.error}</p>}
          {definition && (
            <div className="meta-grid">
              <Wire
                label="Declared by"
                value={
                  definition.source === 'workspace'
                    ? registry
                      ? `workspace (${definition.path}) and registry`
                      : `workspace (${definition.path})`
                    : 'registry'
                }
              />
              {registry?.group && <Wire label="Group" value={registry.group} />}
              {registry?.envelope && <Wire label="Envelope" value={registry.envelope} />}
              {registry?.channels && registry.channels.length > 0 && (
                <Wire label="Registry channels" value={registry.channels.join(', ')} />
              )}
              {registry?.dataschemaurl && (
                <div className="meta">
                  <span className="meta-label">Schema pin</span>
                  <a
                    className="meta-value"
                    href={registry.dataschemaurl}
                    target="_blank"
                    rel="noreferrer"
                    title={registry.dataschemaurl}
                  >
                    <OpenInNewIcon className="icon" aria-hidden />
                    {registry.dataschemaname ?? registry.dataschemaurl}
                  </a>
                </div>
              )}
            </div>
          )}
          <p className="muted contract-command">
            <code>intropy message show {edge.message}</code>
          </p>
        </Section>
      )}

      <Section title="Schema" icon={CategoryIcon}>
        <SchemaBody edge={edge} contract={contract} state={state} loading={loading} />
      </Section>

      {contract?.fingerprint && (
        <p className="muted contract-fingerprint">fingerprint {contract.fingerprint}</p>
      )}
    </aside>
  )
}

/** SchemaBody picks the schema to render: the host's contract schema first
 *  (what the code actually serializes), the registry's otherwise; and when
 *  there is none, the command's reason. */
function SchemaBody({
  edge,
  contract,
  state,
  loading,
}: {
  edge: ContractEdge
  contract?: Contract
  state: MessageState | null
  loading: boolean
}) {
  if (contract?.schema) {
    return (
      <>
        <p className="muted contract-schema-source">From the system host's contract.</p>
        <SchemaTree schema={contract.schema} />
      </>
    )
  }
  if (!edge.message) {
    return (
      <p className="muted">
        This record predates message wiring, so there is no message to look the schema up by.
      </p>
    )
  }
  if (loading) return <p className="muted">Reading the schema…</p>
  if (state?.schema) {
    return (
      <>
        <p className="muted contract-schema-source">
          From the registry: <code>intropy message show {edge.message} --schema</code>
        </p>
        <SchemaTree schema={state.schema} />
      </>
    )
  }
  if (state?.schemaError) return <p className="contract-error">{state.schemaError}</p>
  return null
}

function Wire({ label, value }: { label: string; value: string }) {
  return (
    <div className="meta">
      <span className="meta-label">{label}</span>
      <span className="meta-value">{value}</span>
    </div>
  )
}

/** list renders the components on one end of the wire, marking this one. The
 *  topology's publisher/subscriber lists are the source; the component the
 *  message was clicked from is annotated rather than repeated blindly. */
function list(names: string[] | undefined, self: string): string {
  if (!names || names.length === 0) return '—'
  return names.map((n) => (n === self ? `${n} (this)` : n)).join(', ')
}

